def is_banned_char(c):
    return c in "@#$%^&*(){}[]|\\~:`"

def find_images(height, width, webpage):
    images = []
    visited = set()

    for i in range(height):
        for j in range(width):
            if webpage[i][j] == '+' and (i, j) not in visited:
                # Find the border of the image
                top, bottom, left, right = i, i, j, j
                queue = [(i, j)]

                while queue:
                    x, y = queue.pop(0)
                    visited.add((x, y))

                    # Check up
                    if x > 0 and webpage[x-1][y] == '+':
                        queue.append((x-1, y))
                        top = min(top, x-1)
                    # Check down
                    if x < height - 1 and webpage[x+1][y] == '+':
                        queue.append((x+1, y))
                        bottom = max(bottom, x+1)
                    # Check left
                    if y > 0 and webpage[x][y-1] == '+':
                        queue.append((x, y-1))
                        left = min(left, y-1)
                    # Check right
                    if y < width - 1 and webpage[x][y+1] == '+':
                        queue.append((x, y+1))
                        right = max(right, y+1)

                # Extract the content of the image
                image_content = []
                for x in range(top + 1, bottom):
                    row = []
                    for y in range(left + 1, right):
                        row.append(webpage[x][y])
                    image_content.append(row)

                images.append((top, bottom, left, right, image_content))

    return images

def remove_ads(height, width, webpage, images):
    for top, bottom, left, right, content in images:
        for row in content:
            for char in row:
                if is_banned_char(char):
                    # Replace the entire image with whitespace
                    for x in range(top, bottom + 1):
                        for y in range(left, right + 1):
                            webpage[x] = webpage[x][:y] + ' ' + webpage[x][y+1:]
                    break
            else:
                continue
            break

    return webpage

